    private static void add(List<Problem> list, String title, String desc, String diff, String topic, String time, String space, String javaCode, String sampleIn, String sampleOut) {
        Problem p = new Problem();
        p.setTitle(title);
        p.setDescription(desc);
        p.setDifficulty(diff);
        p.setTopic(topic);
        p.setOptimalTimeComplexity(time);
        p.setOptimalSpaceComplexity(space);
        p.setStarterCodeJava(javaCode);
        p.getTestCases().add(new TestCase(p, sampleIn, sampleOut, false));
        list.add(p);
    }
